$file = 'c:\\xampp\\htdocs\\masmifhda\\.agents\\skills\\zamrud-ui\\SKILL.md';
$content = "\n\n## 16. Modal Styling (Z-Modal)\n**CRITICAL**: When creating modals/popups in Zamrud UI, DO NOT use custom inline styles or `.z-modal-content`. You MUST use the following exact structure:\n```html\n<div id=\"modalId\" class=\"z-modal-ov\">\n    <div class=\"z-modal\">\n        <div class=\"z-modal-head\">\n            <h3 class=\"z-modal-title\"><i data-lucide=\"ICON\"></i> Title Here</h3>\n            <button class=\"z-modal-close\" onclick=\"document.getElementById('modalId').classList.remove('open')\"><i data-lucide=\"x\"></i></button>\n        </div>\n        <form action=\"...\" method=\"POST\">\n            <div class=\"z-modal-body\">\n                <!-- form inputs with .z-form-group and .z-input -->\n            </div>\n            <div class=\"z-modal-foot\">\n                <button type=\"button\" class=\"z-btn z-btn-secondary\" onclick=\"document.getElementById('modalId').classList.remove('open')\">Batal</button>\n                <button type=\"submit\" class=\"z-btn z-btn-primary\">Simpan</button>\n            </div>\n        </form>\n    </div>\n</div>\n```\nTo open the modal, use `document.getElementById('modalId').classList.add('open')`.";
file_put_contents($file, $content, FILE_APPEND);
echo "Added rule to SKILL.md";
